To investigate the effect of multiple transactions, we start by studying the non-overlapping averaged TVA (ATVA)  matrix, ${\mathcal A}_N$, which is defined as

\begin{equation}
{\mathcal A}_N :=
\dfrac{\sum_{i=1}^N |\Delta \overline{{\bf X}}_{2i}|^2}{N} \cdot
\sum_{i=1}^N \dfrac{\Delta\overline{{\bf X}}_{2i} \Delta\overline{{\bf X}}_{2i}^T}{|\Delta\overline{{\bf X}}_{2i}|^2}
= \dfrac{\sum_{i=1}^N |\Delta \overline{{\bf X}}_{2i}|^2}{p}
\cdot \widetilde{\boldsymbol{\Sigma}},
\end{equation}
where $N=\lfloor n/2 \rfloor$, $\widetilde{\boldsymbol{\Sigma}}=\dfrac pN \sum_{i=1}^N \dfrac{\Delta\overline{{\bf X}}_{2i} \Delta\overline{{\bf X}}_{2i}^T}{|\Delta\overline{{\bf X}}_{2i}|^2} $.

Instead of the latent process $({\bf X}_t)$, the observed contaminated process $({\bf Y}_t)$ is usually assumed to follow the additive model
\begin{equation}
{\bf Y}_{t} = {\bf X}_{t} + \bm\varepsilon_{t}, \hspace{1cm} \text{for~} t\in [0,1], \end{equation}
where $\bm\varepsilon_{t} = (\varepsilon_{t}^{(1)}, \cdots,\varepsilon_{t}^{(p)})^\mathrm{T}$ denotes the noise process.

The PA-ATVA matrix is then defined as
\begin{equation*}
{\mathcal{\bm B}}_{M}:= 3\frac{\sum_{i=1}^M|\Delta\widetilde{\overline{\bf{Y}}}_{2i}|^2}{M}\cdot \sum_{i=1}^M\frac{\Delta\widetilde{\overline{\bf{Y}}}_{2i}(\Delta\widetilde{\overline{\bf{Y}}}_{2i})^{\mathrm{T}}}{|\Delta\widetilde{\overline{\bf{Y}}}_{2i}|^2} =  3\frac{\sum_{i=1}^M|\Delta\widetilde{\overline{\bf{Y}}}_{2i}|^2}{p}\cdot\widetilde{\bm{\Xi}},
\end{equation*}
where
\begin{equation}
\widetilde{\bm{\Xi}} := \frac{p}{M} \sum_{i=1}^M\frac{\Delta\widetilde{\overline{\bf{Y}}}_{2i}(\Delta\widetilde{\overline{\bf{Y}}}_{2i})^{\mathrm{T}}}{|\Delta\widetilde{\overline{\bf{Y}}}_{2i}|^2}. \end{equation}

Then the averaged nonlinear shrinkage (ANS) estimator of ICV is defined as
\begin{equation*}
\widehat{\boldsymbol{\Sigma}}_{\textrm{ANS}}:= \hat{\theta}_p\cdot\frac{1}{B} \sum_{k=1}^B \widetilde{\bm{\Xi}}^{(k)}_{\textrm{ANS}}, ~~\widetilde{\bm{\Xi}}^{(k)}_{\textrm{ANS}} = \widetilde{\bf U}_1^{(k)} \textrm{diag}((\widetilde{\bf U}_1^{(k)})^{{\mathrm{T}}} \widetilde{\boldsymbol{\Xi}}_2^{(k)}\widetilde{\bf U}_1^{(k)}) (\widetilde{\bf U}_1^{(k)})^{{\mathrm{T}}},
\end{equation*}
where $\textrm{diag}({\bf A})$ sets all non-diagonal elements of matrix ${\bf A}$ to zero.

To this end, $M_{\tau_1}$ is chosen using the following criterion,
\begin{equation}\arg\min\limits_{M_{\tau_1}\in \mathcal{G}} \bigg| \bigg|  \frac{1}{B} \sum_{k = 1}^B (\widetilde{\bm{\Xi}}^{(k)}_{\textrm{ANS}} -  \widetilde{\bm{\Xi}}_2^{(k)}) \bigg| \bigg|_F^2, \end{equation}
where
\begin{equation}
\begin{split}
\mathcal{G} = \bigg[2M_{\tau}^{1/2}, 0.2M_{\tau}, 0.4M_{\tau},
0.6M_{\tau}, 0.8M_{\tau},
 M_{\tau} - 2.5M_{\tau}^{1/2}, M_{\tau} - 1.5M_{\tau}^{1/2}\bigg]
\end{split} \end{equation}
is the candidate set for $M_{\tau_1}$, recommended by \cite{Lam2016} and \cite{Lametal2017}.

